package org.sleepwell.app;
import org.junit.Test;
import static org.junit.Assert.*;
@org.junit.runner.RunWith(org.junit.runners.JUnit4.class)
public class QrScanSessionTest {
 static final class Camera implements QrScanSession.Port {QrScanSession.Listener listener;int starts,closes;boolean failStart,failClose;public void start(QrScanSession.Listener l){starts++;listener=l;if(failStart)throw new IllegalStateException();}public void close(){closes++;if(failClose)throw new IllegalStateException();}}
 static final class Output implements QrScanSession.Effects {boolean live=true;int captures,errors;public boolean current(){return live;}public void captured(String h){captures++;}public void error(String e){errors++;}}
 @Test public void captureReleasesCameraAndOldCallbackCannotCaptureAgain(){Camera p=new Camera();Output e=new Output();QrScanSession s=new QrScanSession(p,e);s.start();QrScanSession.Listener old=p.listener;old.captured(MorningCode.digest("one"));assertEquals(1,e.captures);assertTrue(s.released());assertEquals(QrScanSession.State.CAPTURED,s.state());old.captured(MorningCode.digest("two"));assertEquals(1,e.captures);s.start();old.error("stale");assertEquals(0,e.errors);p.listener.captured(MorningCode.digest("two"));assertEquals(2,e.captures);}
 @Test public void ownerLossReleasesAndRevokesEvenIfOldOwnerReturns(){Camera p=new Camera();Output e=new Output();QrScanSession s=new QrScanSession(p,e);s.start();QrScanSession.Listener old=p.listener;e.live=false;old.captured(MorningCode.digest("one"));assertTrue(s.released());assertEquals(QrScanSession.State.CLOSED,s.state());e.live=true;old.captured(MorningCode.digest("one"));assertEquals(0,e.captures);s.start();p.listener.captured(MorningCode.digest("one"));assertEquals(1,e.captures);}
 @Test public void pauseAndStartFailureInvalidateQueuedFrames(){Camera p=new Camera();Output e=new Output();QrScanSession s=new QrScanSession(p,e);s.start();QrScanSession.Listener old=p.listener;s.close();old.captured(MorningCode.digest("one"));assertEquals(0,e.captures);p.failStart=true;s.start();assertEquals(1,e.errors);assertEquals(QrScanSession.State.ERROR,s.state());assertTrue(s.released());}
 @Test public void failedReleaseBlocksCaptureAndRearmUntilOwnedReleaseSucceeds(){Camera p=new Camera();Output e=new Output();QrScanSession s=new QrScanSession(p,e);s.start();p.failClose=true;p.listener.captured(MorningCode.digest("one"));assertEquals(0,e.captures);assertFalse(s.released());assertEquals(1,e.errors);s.start();assertEquals(1,p.starts);assertEquals(2,e.errors);p.failClose=false;s.close();s.start();assertEquals(2,p.starts);p.listener.captured("invalid");assertEquals(3,e.errors);assertEquals(0,e.captures);assertTrue(s.released());}
}
